-- ============================================================================
-- eia_district_emissions: Annual congressional district electricity generation
-- and carbon dioxide emissions aggregated from EIA plant surveys (1993-2016)
-- Generated by: analysis/eia-district-emissions.R
-- ============================================================================

DROP TABLE IF EXISTS eia_district_emissions;

CREATE TABLE eia_district_emissions (
    year INTEGER NOT NULL,
    congress INTEGER NOT NULL,
    state_code TEXT NOT NULL,
    district_number INTEGER NOT NULL DEFAULT 0,
    net_generation_mwh REAL,
    fuel_mmbtu REAL,
    co2_metric_tons REAL,
    plant_count INTEGER,
    PRIMARY KEY (year, state_code, district_number),
    FOREIGN KEY (state_code) REFERENCES states(state_code)
);

CREATE INDEX IF NOT EXISTS idx_eia_dist_emit_cong ON eia_district_emissions(congress, state_code, district_number);
CREATE INDEX IF NOT EXISTS idx_eia_dist_emit_year ON eia_district_emissions(year);
